local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- APR-only input overlays. Native binding groups and saved bindings stay owned
-- by Blizzard; secure hide/combat handlers release these temporary overrides.
local Pad, UI = APR.Gamepad, APR.UI
local pending, serial = false, 0
Pad.inputHandlers = setmetatable({}, { __mode = "k" })

function Pad:IsInputOwner(owner)
    return self:IsEnabled()
        and not InCombatLockdown()
        and owner:IsVisible()
        and SmartNavigation:GetActiveFrame() == owner
end--[[APR_DIAG]]
Pad.IsInputOwner = APRTrace("APR-Core/integrations/GamepadInput.lua:12:Pad:IsInputOwner#1", Pad.IsInputOwner)--[[/APR_DIAG]]

function Pad:DispatchInput(owner, key, down)
    local entry = self.inputHandlers[owner]
    if not entry or not self:IsInputOwner(owner) or (entry.wantsKey and not entry.wantsKey(key)) then return end
    local callback = entry.buttons[key]
    if callback then callback(down) end
end--[[APR_DIAG]]
Pad.DispatchInput = APRTrace("APR-Core/integrations/GamepadInput.lua:17:Pad:DispatchInput#2", Pad.DispatchInput)--[[/APR_DIAG]]

function Pad:RefreshInputOwner()
    if InCombatLockdown() then return end
    local owner = self:IsEnabled() and SmartNavigation:GetActiveFrame()
    local chosen = owner and self.inputHandlers[owner]
    if chosen and not owner:IsVisible() then chosen = nil end
    for _, entry in pairs(self.inputHandlers) do
        if entry.router and entry.router:IsShown() then entry.router:Hide() end
        if entry ~= chosen and entry.active and entry.release then entry.release() end
        entry.active = nil
    end
    if not chosen or not chosen.router then return end
    for index, key in ipairs(chosen.keys) do
        chosen.router:SetAttribute("enabled" .. index, not chosen.wantsKey or chosen.wantsKey(key))
    end
    chosen.active = true
    chosen.router:Show()
end--[[APR_DIAG]]
Pad.RefreshInputOwner =
    APRTrace("APR-Core/integrations/GamepadInput.lua:24:Pad:RefreshInputOwner#3", Pad.RefreshInputOwner)--[[/APR_DIAG]]

function Pad:QueueInputRefresh()
    if pending then return end
    pending = true
    local function refresh()
        pending = false
        self:RefreshInputOwner()
    end--[[APR_DIAG]]
    refresh = APRTrace("APR-Core/integrations/GamepadInput.lua:45:refresh#5", refresh)--[[/APR_DIAG]]
    if C_Timer and C_Timer.After then
        C_Timer.After(0, refresh)
    else
        refresh()
    end
end--[[APR_DIAG]]
Pad.QueueInputRefresh =
    APRTrace("APR-Core/integrations/GamepadInput.lua:42:Pad:QueueInputRefresh#4", Pad.QueueInputRefresh)--[[/APR_DIAG]]

function Pad:RegisterInputHandler(owner, settings)
    if self.inputHandlers[owner] then return end
    local entry = settings
    entry.keys = {}
    for key in pairs(entry.buttons) do
        entry.keys[#entry.keys + 1] = key
    end
    table.sort(entry.keys)
    self.inputHandlers[owner] = entry
    if RegisterStateDriver and not InCombatLockdown() then
        serial = serial + 1
        local name = "APRGamepadInput" .. serial
        local router = CreateFrame("Frame", name, UIParent, "SecureHandlerShowHideTemplate,SecureHandlerStateTemplate")
        entry.router = router
        router:Hide()
        router:SetSize(1, 1)
        router:SetPoint("CENTER")
        router:SetFrameStrata("TOOLTIP")
        router:SetFrameLevel(10000)
        router:EnableMouse(false)
        router:SetAttribute("keyCount", #entry.keys)
        router:SetAttribute(
            "_onshow",
            [[
            for index = 1, self:GetAttribute("keyCount") do
                if self:GetAttribute("enabled" .. index) then
                    self:SetBindingClick(true, self:GetAttribute("key" .. index), self:GetAttribute("button" .. index))
                end
            end
        ]]
        )
        router:SetAttribute("_onhide", [[ self:ClearBindings() ]])
        router:SetAttribute("_onstate-combat", [[ if newstate == "1" then self:Hide() end ]])
        for index, key in ipairs(entry.keys) do
            local buttonName = name .. "Button" .. index
            local button = CreateFrame("Button", buttonName, router)
            button:SetSize(1, 1)
            button:SetPoint("CENTER")
            button:EnableMouse(false)
            button:RegisterForClicks("AnyDown", "AnyUp")
            button:SetScript(
                "OnClick", --[[APR_DIAG]]
                APRTrace(
                    "APR-Core/integrations/GamepadInput.lua:83:callback#7", --[[/APR_DIAG]]
                    function(_, _, down) self:DispatchInput(owner, key, down) end --[[APR_DIAG]]
                ) --[[/APR_DIAG]]
            )
            router:SetAttribute("key" .. index, key)
            router:SetAttribute("button" .. index, buttonName)
        end
        if entry.stick then
            router:EnableGamePadStick(true)
            router:SetScript(
                "OnGamepadStick", --[[APR_DIAG]]
                APRTrace("APR-Core/integrations/GamepadInput.lua:89:callback#8", --[[/APR_DIAG]] function(_, stick, x, y)
                    if self:IsInputOwner(owner) then return entry.stick(stick, x, y) end
                    return true
                end--[[APR_DIAG]]) --[[/APR_DIAG]]
            )
        end
        RegisterStateDriver(router, "combat", "[combat] 1; 0")
    end
    owner:HookScript(
        "OnShow", --[[APR_DIAG]]
        APRTrace(
            "APR-Core/integrations/GamepadInput.lua:96:callback#9", --[[/APR_DIAG]]
            function() self:QueueInputRefresh() end --[[APR_DIAG]]
        ) --[[/APR_DIAG]]
    )
    owner:HookScript(
        "OnHide", --[[APR_DIAG]]
        APRTrace("APR-Core/integrations/GamepadInput.lua:97:callback#10", --[[/APR_DIAG]] function()
            if entry.release then entry.release() end
            self:QueueInputRefresh()
        end--[[APR_DIAG]]) --[[/APR_DIAG]]
    )
    if EventRegistry and not self.inputFocusRegistered then
        self.inputFocusRegistered = true
        EventRegistry:RegisterCallback(
            "Gamepad.RefreshFrameFocus", --[[APR_DIAG]]
            APRTrace(
                "APR-Core/integrations/GamepadInput.lua:103:callback#11", --[[/APR_DIAG]]
                function() self:QueueInputRefresh() end --[[APR_DIAG]]
            ) --[[/APR_DIAG]],
            self
        )
    end
    self:QueueInputRefresh()
end--[[APR_DIAG]]
Pad.RegisterInputHandler =
    APRTrace("APR-Core/integrations/GamepadInput.lua:52:Pad:RegisterInputHandler#6", Pad.RegisterInputHandler)--[[/APR_DIAG]]

local watcher = CreateFrame("Frame")
watcher:RegisterEvent("PLAYER_REGEN_ENABLED")
watcher:RegisterEvent("PLAYER_REGEN_DISABLED")
if APR.RegisterSupportedEvent then APR:RegisterSupportedEvent(watcher, "GAME_PAD_DISCONNECTED") end
watcher:SetScript(
    "OnEvent", --[[APR_DIAG]]
    APRTrace("APR-Core/integrations/GamepadInput.lua:112:callback#12", --[[/APR_DIAG]] function(_, event)
        if event == "PLAYER_REGEN_DISABLED" or event == "GAME_PAD_DISCONNECTED" then
            for _, entry in pairs(Pad.inputHandlers) do
                if entry.release then entry.release() end
            end
        else
            Pad:QueueInputRefresh()
        end
    end--[[APR_DIAG]]) --[[/APR_DIAG]]
)

function Pad:CreateInputHint(parent, label, key, fallback)
    local hint = CreateFrame("Frame", nil, parent)
    hint:SetSize(180, 28)
    hint:EnableMouse(false)
    hint.key, hint.label, hint.fallback = key, label, fallback
    hint.icon = hint:CreateTexture(nil, "ARTWORK")
    hint.icon:SetSize(26, 26)
    hint.icon:SetPoint("LEFT")
    hint.badge = UI:Panel(hint)
    hint.badge:SetSize(28, 26)
    hint.badge:SetPoint("LEFT")
    hint.badge:EnableMouse(false)
    hint.badge.text = UI:Label(hint.badge, fallback or "", 13, "accent")
    hint.badge.text:SetPoint("CENTER")
    hint.text = UI:Label(hint, label, 14)
    hint.text:SetPoint("LEFT", 34, 0)
    hint.text:SetPoint("RIGHT")
    hint.text:SetWordWrap(false)
    self:RefreshInputHint(hint)
    return hint
end--[[APR_DIAG]]
Pad.CreateInputHint = APRTrace("APR-Core/integrations/GamepadInput.lua:118:Pad:CreateInputHint#13", Pad.CreateInputHint)--[[/APR_DIAG]]

function Pad:RefreshInputHint(hint)
    local utility = InputIconTextureSetUtility
    local atlas = hint.key
        and utility
        and utility.GetNormalActiveInputIconButtonTexture
        and utility.GetNormalActiveInputIconButtonTexture(hint.key)
    -- InputIconTextureSetUtility returns an atlas name, never a file texture.
    if atlas then hint.icon:SetAtlas(atlas) end
    hint.icon:SetShown(atlas ~= nil)
    hint.badge:SetShown(atlas == nil and hint.fallback ~= nil)
    hint.text:SetText(hint.label)
end--[[APR_DIAG]]
Pad.RefreshInputHint =
    APRTrace("APR-Core/integrations/GamepadInput.lua:134:Pad:RefreshInputHint#14", Pad.RefreshInputHint)--[[/APR_DIAG]]
